class Solution:
    def mostPoints(self, questions: list[list[int]]) -> int:
        n = len(questions)
        dp = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            points, bp = questions[i]
            nxt = i + bp + 1
            solve = points + (dp[nxt] if nxt < n else 0)
            dp[i] = max(dp[i + 1], solve)
        return dp[0]

